import Foundation

/// The user-owned libraries next to the built-in catalog ("Standard"). Stored in the global library folder.
public enum LibrarySection: String, Codable, CaseIterable, Sendable, Identifiable {
    /// Furniture the user saved from a project.
    case own
    /// Furniture the user plans to buy or build (carries a purchase status).
    case planned
    /// Furniture generated by an assistant (for example from a photo).
    case ai

    public var id: String { rawValue }
    public var title: String {
        switch self {
        case .own: "Own"
        case .planned: "Planned"
        case .ai: "AI"
        }
    }
}

/// A user-made group of library entries ("My Furniture" shows one collapsible block per category).
public struct LibraryCategory: Codable, Sendable, Equatable, Identifiable {
    public var id: UUID
    public var name: String
    /// Position in the list (0 is first); `LibraryStore` keeps the values dense.
    public var order: Int
    public var createdAt: Date

    public init(id: UUID = UUID(), name: String, order: Int = 0, createdAt: Date = Date()) {
        self.id = id; self.name = name; self.order = order; self.createdAt = createdAt
    }

    private enum CodingKeys: String, CodingKey { case id, name, order, createdAt }

    public init(from decoder: Decoder) throws {
        let c = try decoder.container(keyedBy: CodingKeys.self)
        id = try c.decode(UUID.self, forKey: .id)
        name = try c.decode(String.self, forKey: .name)
        order = try c.decodeIfPresent(Int.self, forKey: .order) ?? 0
        createdAt = try c.decodeIfPresent(Date.self, forKey: .createdAt) ?? Date(timeIntervalSince1970: 0)
    }
}

/// Decodes one array element without failing the array: a damaged element becomes nil.
struct Failable<T: Decodable>: Decodable {
    let value: T?
    init(from decoder: Decoder) throws { value = try? T(from: decoder) }
}

/// One saved piece (or arrangement) of furniture in the global library. The furniture itself (designs, materials,
/// products, asset bytes) lives in `entries/<id>.json` as a `FurnitureTransfer`; the index only carries what lists need.
public struct LibraryEntry: Codable, Sendable, Equatable, Identifiable {
    public var id: UUID
    public var section: LibrarySection
    public var name: String
    public var description: String
    /// Overall size of the saved furniture (mm).
    public var size: Size3
    public var materialNames: [String]
    public var tags: [String]
    /// Purchase status; used by the Planned section.
    public var status: PurchaseStatus?
    /// Design of the first saved piece inside the stored transfer (used for the thumbnail).
    public var definitionId: UUID?
    /// Counts up whenever the stored furniture changes; names the cached thumbnail.
    public var rev: Int64
    /// Parametric template and parameters when the entry was built with the furniture builder.
    public var spec: ParametricSpec?
    /// Names of photo files in the library's `assets` folder (reference photos of the piece).
    public var photoAssetNames: [String]
    public var createdAt: Date
    /// Category the entry belongs to; nil (or an id that no category has) means "Unsorted".
    public var categoryId: UUID?

    public init(id: UUID = UUID(), section: LibrarySection = .own, name: String, description: String = "", size: Size3,
                materialNames: [String] = [], tags: [String] = [], status: PurchaseStatus? = nil, definitionId: UUID? = nil,
                rev: Int64 = 1, spec: ParametricSpec? = nil, photoAssetNames: [String] = [], createdAt: Date = Date(),
                categoryId: UUID? = nil) {
        self.id = id; self.section = section; self.name = name; self.description = description; self.size = size
        self.materialNames = materialNames; self.tags = tags; self.status = status; self.definitionId = definitionId
        self.rev = rev; self.spec = spec; self.photoAssetNames = photoAssetNames; self.createdAt = createdAt
        self.categoryId = categoryId
    }

    private enum CodingKeys: String, CodingKey {
        case id, section, name, description, size, materialNames, tags, status, definitionId, rev, spec, photoAssetNames, createdAt, categoryId
    }

    /// A damaged or unknown `spec` becomes nil; it never makes the whole library unreadable.
    public init(from decoder: Decoder) throws {
        let c = try decoder.container(keyedBy: CodingKeys.self)
        id = try c.decode(UUID.self, forKey: .id)
        section = try c.decode(LibrarySection.self, forKey: .section)
        name = try c.decode(String.self, forKey: .name)
        description = try c.decodeIfPresent(String.self, forKey: .description) ?? ""
        size = try c.decode(Size3.self, forKey: .size)
        materialNames = try c.decodeIfPresent([String].self, forKey: .materialNames) ?? []
        tags = try c.decodeIfPresent([String].self, forKey: .tags) ?? []
        status = try c.decodeIfPresent(PurchaseStatus.self, forKey: .status)
        definitionId = try c.decodeIfPresent(UUID.self, forKey: .definitionId)
        rev = try c.decodeIfPresent(Int64.self, forKey: .rev) ?? 1
        spec = try? c.decodeIfPresent(ParametricSpec.self, forKey: .spec)
        photoAssetNames = try c.decodeIfPresent([String].self, forKey: .photoAssetNames) ?? []
        createdAt = try c.decodeIfPresent(Date.self, forKey: .createdAt) ?? Date(timeIntervalSince1970: 0)
        categoryId = try? c.decodeIfPresent(UUID.self, forKey: .categoryId)
    }

    /// Path of the stored furniture relative to the library folder.
    public var transferFile: String { "entries/\(id.uuidString.lowercased()).json" }
}

/// The index file `library.json`. `categories` is optional on disk (files written before categories existed have none),
/// so the format version stays 1: an older build reads the file and only drops the categories when it writes.
public struct LibraryIndex: Codable, Sendable, Equatable {
    public static let currentVersion = 1
    public var version: Int = LibraryIndex.currentVersion
    public var entries: [LibraryEntry] = []
    public var categories: [LibraryCategory] = []
    public init(entries: [LibraryEntry] = [], categories: [LibraryCategory] = []) { self.entries = entries; self.categories = categories }

    private enum CodingKeys: String, CodingKey { case version, entries, categories }

    /// A missing or damaged `categories` list never makes the library unreadable; a damaged single category or entry is skipped.
    public init(from decoder: Decoder) throws {
        let c = try decoder.container(keyedBy: CodingKeys.self)
        version = try c.decode(Int.self, forKey: .version)
        entries = try c.decode([Failable<LibraryEntry>].self, forKey: .entries).compactMap(\.value)
        categories = ((try? c.decodeIfPresent([Failable<LibraryCategory>].self, forKey: .categories)) ?? nil)?.compactMap(\.value) ?? []
    }

    /// Categories in display order.
    public var sortedCategories: [LibraryCategory] {
        categories.enumerated().sorted { ($0.element.order, $0.offset) < ($1.element.order, $1.offset) }.map(\.element)
    }

    public func category(_ id: UUID) -> LibraryCategory? { categories.first { $0.id == id } }

    /// The category the entry is shown in; nil is "Unsorted" (no category, or one that no longer exists).
    public func effectiveCategoryId(_ e: LibraryEntry) -> UUID? {
        guard let id = e.categoryId, categories.contains(where: { $0.id == id }) else { return nil }
        return id
    }
}

/// Search over library entries: every word must occur in name, description, tags, materials, section, status or category name.
public enum LibrarySearch {
    /// Alphabetical by name (case- and accent-insensitive, numbers in natural order); the id breaks ties so the order is stable.
    public static func sortedByName(_ entries: [LibraryEntry]) -> [LibraryEntry] {
        entries.sorted {
            switch $0.name.localizedStandardCompare($1.name) {
            case .orderedAscending: true
            case .orderedDescending: false
            case .orderedSame: $0.id.uuidString < $1.id.uuidString
            }
        }
    }

    public static func matches(_ e: LibraryEntry, query: String, categoryName: String? = nil) -> Bool {
        let words = query.lowercased().split(whereSeparator: \.isWhitespace)
        if words.isEmpty { return true }
        let hay = ([e.name, e.description, e.section.rawValue, e.section.title, e.status?.rawValue ?? "", categoryName ?? ""] + e.tags + e.materialNames)
            .joined(separator: " ").lowercased()
        return words.allSatisfy { hay.contains($0) }
    }

    /// Which category to keep: everything, one category, or only the unsorted entries.
    public enum CategoryFilter: Equatable, Sendable {
        case any, unsorted, category(UUID)
    }

    public static func filter(_ entries: [LibraryEntry], query: String = "", section: LibrarySection? = nil,
                              status: PurchaseStatus? = nil, categories: [LibraryCategory] = [], category: CategoryFilter = .any) -> [LibraryEntry] {
        let index = LibraryIndex(entries: entries, categories: categories)
        return entries.filter { e in
            let eff = index.effectiveCategoryId(e)
            switch category {
            case .any: break
            case .unsorted: if eff != nil { return false }
            case .category(let id): if eff != id { return false }
            }
            let name = eff.flatMap { index.category($0)?.name }
            return (section == nil || e.section == section) && (status == nil || e.status == status) && matches(e, query: query, categoryName: name)
        }
    }
}

/// Drag token of a library row (`roomsmith-library:<entryId>`); separate from the project-to-project transfer token.
public struct LibraryDragToken: Equatable, Sendable {
    public static let prefix = "roomsmith-library:"
    public var entryId: UUID
    public init(entryId: UUID) { self.entryId = entryId }

    public var payload: String { Self.prefix + entryId.uuidString.lowercased() }

    public init?(payload: String) {
        guard payload.hasPrefix(Self.prefix), let id = UUID(uuidString: String(payload.dropFirst(Self.prefix.count))) else { return nil }
        self.entryId = id
    }
}
